CREATE POLICY "admin_story_stickers_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'story-stickers' AND public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "admin_story_stickers_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'story-stickers' AND public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "admin_story_stickers_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'story-stickers' AND public.has_role(auth.uid(), 'admin'::public.app_role));